    const p=draft.proposal,result=await state.supabase.functions.invoke(channel==="email"?"send-proposal-email":"send-proposal-whatsapp",{body:{approved:true,reviewedResponseAt:getOpportunityForItem(item)?.ultima_resposta_cliente_em||null,proposalId:p.id,proposalUrl:getPublicProposalUrl(p),message:body,title:"Atendimento do seu evento",...(channel==="email"?{email:f.elements.destination.value.trim()}:{phone:f.elements.destination.value.trim()})}});
